let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let alertIds = AlertEvidence | where Timestamp {TimeRange:value}
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
AlertInfo
| where Timestamp {TimeRange:value} and AlertId in (alertIds)
| summarize Alerts = dcount(AlertId) by bin(Timestamp, 1d), Severity
| order by Timestamp asc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let clusterAlerts = AlertEvidence | where Timestamp > ago(30d)
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
SecurityIncident
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, Status, Classification, Severity, AlertIds, ClosedTime) by IncidentNumber
| mv-expand AlertId = AlertIds to typeof(string)
| where AlertId in (clusterAlerts)
| summarize Incidents = dcount(IncidentNumber) by Status, Classification = iff(isempty(Classification), 'Unclassified', Classification)
| order by Incidents desc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let clusterAlerts = AlertEvidence | where Timestamp > ago(30d)
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
let inc = materialize(
SecurityIncident
    | where TimeGenerated > ago(30d)
    | summarize arg_max(TimeGenerated, CreatedTime, ClosedTime, AlertIds) by IncidentNumber
    | mv-expand AlertId = AlertIds to typeof(string)
    | where AlertId in (clusterAlerts)
    | distinct IncidentNumber, CreatedTime, ClosedTime);
inc | summarize Incidents = dcount(IncidentNumber) by Timestamp = bin(CreatedTime, 1d)
    | extend Event = 'opened'
| union (inc | where isnotempty(ClosedTime)
    | summarize Incidents = dcount(IncidentNumber) by Timestamp = bin(ClosedTime, 1d)
    | extend Event = 'closed')
| order by Timestamp asc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let alertIds = AlertEvidence | where Timestamp {TimeRange:value}
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
AlertInfo
| where Timestamp {TimeRange:value} and AlertId in (alertIds)
| summarize Alerts = dcount(AlertId) by HourUtc = hourofday(Timestamp), Severity
| order by HourUtc asc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let alertIds = AlertEvidence | where Timestamp {TimeRange:value}
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
AlertInfo
| where Timestamp {TimeRange:value} and AlertId in (alertIds)
// Defender for Cloud container alerts populate Category (the tactic) but often leave
// AttackTechniques empty, so fall back to the category rather than showing nothing.
| extend Technique = iff(isempty(AttackTechniques), strcat('tactic: ', Category), AttackTechniques)
| summarize Alerts = dcount(AlertId), Titles = make_set(Title, 4) by Technique, Severity
| order by Alerts desc
| take 20

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let alertIds = AlertEvidence | where Timestamp {TimeRange:value}
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId;
AlertInfo
| where Timestamp {TimeRange:value} and AlertId in (alertIds)
| summarize Alerts = dcount(AlertId) by DetectionSource, Severity
| order by Alerts desc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
let alertIds = materialize(
AlertEvidence | where Timestamp {TimeRange:value}
    | where ResourceID =~ cluster or CloudResource =~ clusterName | distinct AlertId);
AlertInfo
| where Timestamp {TimeRange:value} and AlertId in (alertIds)
| join kind=leftouter (
    AlertEvidence
    | where Timestamp {TimeRange:value} and AlertId in (alertIds)
    | summarize Entities = make_set(strcat(EntityType, ': ', coalesce(CloudResource, FileName, AccountName, RemoteIP, RemoteUrl, DeviceName)), 8),
              Commands = make_set(ProcessCommandLine, 3)
      by AlertId
  ) on AlertId
| project Timestamp, Severity, Title, Category, DetectionSource, Entities, Commands, AlertId
| order by Timestamp desc
| take 100

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
CloudPolicyEnforcementEvents
| where Timestamp {TimeRange:value} and AzureResourceId =~ cluster and ActionType == 'Deny'
| summarize Denies = count() by KubernetesNamespace
| top 15 by Denies desc

let cluster = '{ClusterId}';
let clusterName = tostring(split(cluster, '/')[-1]);
// The first bucket always spikes: on day one every domain is new. Read the days AFTER it -
// a flat workload should resolve a stable set, so a fresh burst is worth a look.
CloudDnsEvents
| where Timestamp {TimeRange:value} and AzureResourceId =~ cluster
| where '*' in ({Namespace}) or KubernetesNamespace in ({Namespace})
| where isnotempty(DnsQuery)
| summarize FirstSeen = min(Timestamp) by DnsQuery
| summarize NewDomains = dcount(DnsQuery), Examples = make_set(DnsQuery, 5) by Timestamp = bin(FirstSeen, 1d)
| order by Timestamp asc

// NOT make-graph: that builds the WHOLE tenant exposure graph before matching, which cost
// 120s+ on a single-cluster tenant and timed out past 180s. Each hop below is seeded by the
// previous hop's node set, so the edge scan is filtered instead of the graph materialized.
let clusterName = tostring(split('{ClusterId}', '/')[-1]);
let clusterNodes = materialize(ExposureGraphNodes
    | where tostring(EntityIds) has '{ClusterId}'
        or (NodeName =~ clusterName
            and (NodeLabel has 'managedclusters' or set_has_element(Categories, 'kubernetes_cluster')))
    | project NodeId);
let exposed = materialize(ExposureGraphNodes
    | extend Raw = todynamic(NodeProperties).rawData
    | where isnotnull(Raw.exposedToInternet) or isnotnull(Raw.IsInternetFacing)
    | project NodeId, EntryPoint = NodeName, EntryType = NodeLabel);
let h1 = materialize(ExposureGraphEdges
    | where TargetNodeId in ((clusterNodes | project NodeId))
    | project SourceNodeId, EdgeLabel);
let h2 = materialize(ExposureGraphEdges
    | where TargetNodeId in ((h1 | project SourceNodeId))
    | project SourceNodeId, EdgeLabel);
let h3 = ExposureGraphEdges
    | where TargetNodeId in ((h2 | project SourceNodeId))
    | project SourceNodeId, EdgeLabel;
union (h1 | extend Hops = 1), (h2 | extend Hops = 2), (h3 | extend Hops = 3)
| join kind=inner exposed on $left.SourceNodeId == $right.NodeId
| summarize Paths = count(), ShortestPath = min(Hops), Relationships = make_set(EdgeLabel, 4)
      by EntryPoint, EntryType
| order by ShortestPath asc, Paths desc
| take 50

// NOT make-graph: that builds the WHOLE tenant exposure graph before matching, which cost
// 120s+ on a single-cluster tenant and timed out past 180s. Each hop below is seeded by the
// previous hop's node set, so the edge scan is filtered instead of the graph materialized.
let clusterName = tostring(split('{ClusterId}', '/')[-1]);
let clusterNodes = materialize(ExposureGraphNodes
    | where tostring(EntityIds) has '{ClusterId}'
        or (NodeName =~ clusterName
            and (NodeLabel has 'managedclusters' or set_has_element(Categories, 'kubernetes_cluster')))
    | project NodeId);
let targets = materialize(ExposureGraphNodes
    | extend Raw = todynamic(NodeProperties).rawData
    | where isnotnull(Raw.containsSensitiveData) or isnotnull(Raw.criticalityLevel)
    | project NodeId, Asset = NodeName, AssetType = NodeLabel,
            Sensitive = isnotnull(Raw.containsSensitiveData),
            Critical = isnotnull(Raw.criticalityLevel));
let h1 = materialize(ExposureGraphEdges
    | where SourceNodeId in ((clusterNodes | project NodeId))
    | project TargetNodeId, EdgeLabel);
let h2 = materialize(ExposureGraphEdges
    | where SourceNodeId in ((h1 | project TargetNodeId))
    | project TargetNodeId, EdgeLabel);
let h3 = ExposureGraphEdges
    | where SourceNodeId in ((h2 | project TargetNodeId))
    | project TargetNodeId, EdgeLabel;
union (h1 | extend Hops = 1), (h2 | extend Hops = 2), (h3 | extend Hops = 3)
| join kind=inner targets on $left.TargetNodeId == $right.NodeId
| summarize Paths = count(), ShortestPath = min(Hops), Relationships = make_set(EdgeLabel, 4)
      by Asset, AssetType, Sensitive, Critical
| order by ShortestPath asc, Paths desc
| take 50

let clusterId = '{ClusterId}';
let clusterName = tostring(split(clusterId, '/')[-1]);
let rg = tostring(split(clusterId, '/')[4]);
let nodeRgHint = strcat('/mc_', tolower(rg), '_', tolower(clusterName), '_');
let clusterIdentities = materialize(
ExposureGraphNodes
    | where NodeLabel in~ ('managedidentity', 'serviceprincipal')
    | extend Raw = todynamic(NodeProperties).rawData
    | extend Alt = tolower(tostring(Raw.alternativeNames)),
           Display = tostring(Raw.accountDisplayName)
    // three ways an identity belongs to a cluster, all observed in the graph:
    //   control plane  -> alternativeNames carries the cluster resource id
    //   kubelet/addons -> they live in the node resource group MC_<rg>_<cluster>_<region>
    //   workload ids   -> user-assigned identities in the cluster's own resource group
    | where Alt has tolower(clusterId)
        or Alt has nodeRgHint
        or (Alt has strcat('/resourcegroups/', tolower(rg), '/') and Alt has 'userassignedidentities')
    | extend Role = case(
          Display endswith '-agentpool' or Alt has '-agentpool', 'kubelet (node pool)',
          Display startswith 'azurepolicy' or Alt has 'azurepolicy', 'addon: azure policy',
          Display startswith 'omsagent' or Alt has 'omsagent', 'addon: monitoring',
          Alt has tolower(clusterId) and Alt has 'isexplicit=false', 'cluster control plane',
          'workload identity / other')
    | project NodeId, IdentityName = coalesce(Display, NodeName), Role, NodeLabel);
ExposureGraphEdges
| where SourceNodeId in ((clusterIdentities | project NodeId))
| where EdgeLabel in~ ('has permissions to', 'has role on', 'controls access to',
                       'can authenticate as', 'member of', 'has assignment')
| join kind=inner (clusterIdentities) on $left.SourceNodeId == $right.NodeId
| summarize Targets = dcount(TargetNodeId), Examples = make_set(TargetNodeName, 5)
      by Role, IdentityName, EdgeLabel, TargetNodeLabel
| order by Role asc, Targets desc
| take 100

